<script setup lang="ts">
import {ref} from 'vue'
import {onShow,onHide} from '@dcloudio/uni-app'
import {request,navigate,token,type Row} from '../../api/platform'
import {abandonLogin} from '../../features/auth'
import LoginSheet from '../../components/LoginSheet.vue'
import PageState from '../../components/PageState.vue'
const tab=ref('replacement'),rules=ref<Row[]>([]),counts=ref<Record<string,number>>({replacement:0,keyword:0,instant:0}),error=ref(''),loading=ref(false),busy=ref(false),signedIn=ref(false),page=ref(1),total=ref(0),wecomBound=ref<'BOUND'|'UNBOUND'|'UNKNOWN'>('UNKNOWN')
async function syncBound(){try{const settings=await request('GET','/api/v1/me/reminders/settings');const permission=((settings.permissions as Row[])||[])[0];wecomBound.value=typeof permission?.wecomBound==='boolean'?(permission.wecomBound?'BOUND':'UNBOUND'):'UNKNOWN'}catch{}}
const filters:Record<string,string>={replacement:'mode=DAILY&targetType=ARTICLE',keyword:'mode=DAILY&targetType=KEYWORD',instant:'mode=INSTANT'}
async function load(){signedIn.value=!!token();if(!signedIn.value){rules.value=[];return}loading.value=true;error.value='';try{const result=await request('GET','/api/v1/me/reminders/rules?page='+page.value+'&size=20&'+filters[tab.value]);rules.value=result.items;total.value=result.total;for(const key of Object.keys(filters)){const c=await request('GET','/api/v1/me/reminders/rules?size=1&'+filters[key]);counts.value[key]=c.total}}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function switchTab(value:string){if(loading.value||busy.value)return;tab.value=value;page.value=1;void load()}
async function toggle(rule:Row){if(busy.value)return;busy.value=true;error.value='';try{if(!rule.enabled&&rule.mode==='DAILY'){if(wecomBound.value==='UNKNOWN')await syncBound();if(wecomBound.value==='UNBOUND'){const decision=await uni.showModal({title:'需要先绑定企业微信',content:'日常强提醒通过企业微信发送，绑定后回到本页即可开启',confirmText:'去绑定',cancelText:'稍后'});if(decision.confirm)navigate('notification-settings');return}}await request('PUT','/api/v1/me/reminders/rules/'+rule.id,{...rule,enabled:!rule.enabled,expectedVersion:rule.lockVersion});await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onShow(()=>{void load();if(token())void syncBound()});onHide(abandonLogin)
</script><template><view class="page"><view class="hero"><text class="title">我关注的强提醒</text></view><view v-if="!signedIn" class="card"><text>登录后管理强提醒</text><button role="button" @click="navigate('login')">登录</button></view><template v-else><view class="segmented"><button role="button" :class="{active:tab==='replacement'}" @click="switchTab('replacement')">更替 {{ counts.replacement }}</button><button role="button" :class="{active:tab==='keyword'}" @click="switchTab('keyword')">关键词 {{ counts.keyword }}</button><button role="button" :class="{active:tab==='instant'}" @click="switchTab('instant')">及时 {{ counts.instant }}</button></view><PageState :busy="loading" :error="error" :empty="!rules.length&&!loading" empty-text="暂未设置此类提醒" @retry="load"/><view v-for="rule in rules" :key="rule.id" class="card"><text class="card-title" @click="navigate(rule.targetType==='ARTICLE'?'article':'keyword-updates','?id='+rule.targetId)">{{ rule.title||'关注对象' }}</text><text class="muted">{{ rule.enabled?'已开启':'已关闭' }}</text><view class="actions"><button role="button" class="quiet" :disabled="busy" @click="toggle(rule)">{{ rule.enabled?'关闭':'重新开启' }}</button><button role="button" class="secondary" @click="navigate('notification-edit','?id='+rule.id)">修改方式</button></view></view><view class="actions" v-if="total>20"><button role="button" :disabled="page===1||loading" @click="page--;load()">上一页</button><text>{{ page }}</text><button role="button" :disabled="page*20>=total||loading" @click="page++;load()">下一页</button></view><view class="bottom-actions"><button role="button" @click="navigate('notification-add')">新增强提醒</button><button role="button" class="quiet" @click="navigate('notifications')">返回提醒盒子</button></view></template><LoginSheet/></view></template>
